import json
r=json.load(open('/workspace/runtime_context.json'))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k"'!='"'context' and k"'!='"'study_schema': print(k,json.dumps(v,ensure_ascii=False))
c=r['context']; print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge']: print(k,json.dumps(v,ensure_ascii=False))
print('HISTORY SUMMARY')
for t in c['history']:
 print(json.dumps({k:t.get(k) for k in ['id','parent','role','status','config','validation','parameters','dense_parameters','train_seconds','wall_seconds','error','note'] if k"'!='"'validation'}))
 print('METRICS',json.dumps({k:v for k,v in t.get('validation',{}).items() if k in ['auc','logloss','slices','examples_per_second','batch_latency_ms_p50','batch_latency_ms_p95']}))
PY"

